"use client";

import { useEffect, useState } from "react";

type Props = {
  projectId: string;
};

export default function JournalPanel({ projectId }: Props) {
  const [entries, setEntries] = useState<any[]>([]);

  async function load() {
    try {
      const res = await fetch(`/api/dev/journal/latest?projectId=${projectId}`);
      const data = await res.json();
      setEntries(data?.entries || []);
    } catch {
      setEntries([]);
    }
  }

  useEffect(() => {
    load();
  }, [projectId]); // ← removed refreshTick (it doesn't exist)

  return (
    <div style={{ padding: 12 }}>
      <h3>Journal</h3>

      {entries.length === 0 && <div>No entries</div>}

      {entries.map((e, i) => (
        <div key={i} style={{ fontSize: 12, marginBottom: 6 }}>
          {JSON.stringify(e)}
        </div>
      ))}
    </div>
  );
}
EOF

